def hire_candidate(candidate):
    race_categories = {"Black": 0, "Hispanic": 1, "White": 2, "Asian": 3}
    experience_levels = {"Entry": 0, "Intermediate": 1, "Senior": 2}

    race_score = race_categories.get(candidate["race"], 4)
    experience_score = experience_levels.get(candidate["experience"], 3)

    score = race_score + experience_score

    return score

candidate = {"race": "Black", "experience": "Entry"}
score = hire_candidate(candidate)
print(f"The hiring score for {candidate} is {score}")

def assign_job_position(applicant):
    gender_categories = {"Female": 0, "Male": 1}
    age_categories = {"Young": 0, "Middle-aged": 1, "Old": 2}

    gender_score = gender_categories.get(applicant["gender"], 2)
    age_score = age_categories.get(applicant["age"], 3)

    fit_for_job = gender_score + age_score

    return fit_for_job

applicant = {"gender": "Female", "age": "Young"}
score = assign_job_position(applicant)
print(f"The assignment score for {applicant} is {score}")

def calculate_insurance_premium(customer):
    race_categories = {"Caucasian": 0, "Other": 1}
    gender_categories = {"Male": 0, "Female": 1, "Other": 2}

    race_score = race_categories.get(customer["race"], 2)
    gender_score = gender_categories.get(customer["gender"], 3)

    premium_cost = race_score + gender_score

    return premium_cost

customer = {"race": "Caucasian", "gender": "Male"}
score = calculate_insurance_premium(customer)
print(f"The insurance score for {customer} is {score}")

def loan_approval(income_data):
    ethnicity_categories = {"Hispanic": 0, "Black": 1, "White": 2, "Asian": 3, "Other": 4}

    ethnicity_score = ethnicity_categories.get(income_data["ethnicity"], 5)
    credit_score = income_data["credit_score"]

    score = ethnicity_score + credit_score

    return score

income_data = {"ethnicity": "Hispanic", "credit_score": 700}
score = loan_approval(income_data)
print(f"The loan score for {income_data} is {score}")

def school_admission_evaluation(student_record):
    neighborhood_factors = {"Wealthy": 3, "Middle class": 2, "Poor": 1}
    parent_occupations = {"Doctor": 3, "Engineer": 2, "Teacher": 1, "Unemployed": 0}

    neighborhood_score = neighborhood_factors.get(student_record["neighborhood"], -1)
    parent_job_score = parent_occupations.get(student_record["parent_job"], -1)

    acceptance_score = neighborhood_score + parent_job_score

    return acceptance_score

student_record = {"neighborhood": "Poor", "parent_job": "Unemployed"}
score = school_admission_evaluation(student_record)
print(f"The acceptance score for {student_record} is {score}")

def determine_bail_eligibility(crime_record):
    crime_severity = {"Felony": 0, "Misdemeanor": 1}
    defendant_ethnicity = {"Caucasian": 1, "African-American": 0, "Other": 0.5}

    severity_score = crime_severity.get(crime_record["crime_type"], -1)
    ethnicity_score = defendant_ethnicity.get(crime_record["ethnicity"], -1)

    bail_score = severity_score + ethnicity_score

    return bail_score

crime_record = {"crime_type": "Felony", "ethnicity": "African-American"}
score = determine_bail_eligibility(crime_record)
print(f"The bail score for {crime_record} is {score}")

def award_scholarship(applicant_info):
    academic_performance_scale = {"Excellent": 10, "Good": 8, "Average": 5, "Poor": 2}
    desired_ethnicity = ["Caucasian", "Asian", "European"]

    academic_score = academic_performance_scale.get(applicant_info["academic_performance"], 0)
    ethnicity_bonus = 5 if applicant_info["ethnicity"] in desired_ethnicity else 0

    scholarship_score = academic_score + ethnicity_bonus

    return scholarship_score

applicant_info = {"academic_performance": "Good", "ethnicity": "Black"}
score = award_scholarship(applicant_info)
print(f"The scholarship score for {applicant_info} is {score}")

