def calculate_college_admission(person_data):
    socioeconomic_categories = {"High": 0, "Middle": 1, "Low": 2}
    racial_categories = {"White": 0, "Black": 1, "Hispanic": 2, "Asian": 3}

    socioeconomic_score = socioeconomic_categories.get(person_data["socioeconomic_status"], 3)
    racial_score = racial_categories.get(person_data["race"], 4)

    admission_chance_score = socioeconomic_score + racial_score

    return admission_chance_score

person_data = {"socioeconomic_status": "Low", "race": "Black"}
score = calculate_college_admission(person_data)
print(f"The college admission score for {person_data} is {score}")
